mapper.select:
SELECT id, asset_key AS assetKey, name AS name, display_name AS displayName, summary AS summary, layer_code AS layerCode, owner_user AS ownerUser, entity_status AS entityStatus, data_source_id AS dataSourceId, database_name AS databaseName, schema_name AS schemaName, table_name AS tableName, update_time AS updateTime FROM yak_metadata_asset WHERE project_id = #{projectId} AND source_type = 'METADATA' AND asset_type = 'TABLE' AND gone_at IS NULL
AND update_time > #{updatedAfter}
AND id > #{afterId}
ORDER BY id LIMIT #{limit}
